-- Full Customer Master backfill: address, GSTIN, primary contact person,
-- contact email, contact phone -- for EVERY customer, not just IKEA.
-- Source: the uploaded "Customer Master.xlsx" (Master_info_of_Account sheet)
-- -- this is the same file the real customers import was originally built
-- from, matched here by the customers.code you already have (e.g. C07924).
--
-- 894 real customer rows matched (Account Type = Customer or
-- Customer/Vendor, Code in the C##### format actually used in the live
-- customers table -- a further ~99 rows in the source file use legacy/
-- inconsistent codes -- e.g. plain numbers, vendor abbreviations, "TEMP01")
-- that don't match anything here and are safely skipped, not guessed at.
--
-- Every SET uses COALESCE, so nothing you've already filled in by hand (or
-- via the two earlier IKEA-specific migrations) gets overwritten -- this
-- only fills in what's still genuinely blank.
--
-- Idempotent: safe to re-run.

alter table public.customers
  add column if not exists contact_email text,
  add column if not exists contact_phone text;

update public.customers c
set
  address = coalesce(c.address, m.address),
  gstin = coalesce(c.gstin, m.gstin),
  default_attention_person = coalesce(c.default_attention_person, m.contact),
  contact_email = coalesce(c.contact_email, m.email),
  contact_phone = coalesce(c.contact_phone, m.phone)
